use serde::{Deserialize, Serialize};
use std::collections::HashMap;

fn main () -> Result < () , Box < dyn std :: error :: Error > > { println ! ("cargo:rerun-if-changed=patches") ; let manifest_dir = PathBuf :: from (env :: var ("CARGO_MANIFEST_DIR") ?) ; let patches_dir = manifest_dir . join ("patches") ; eprintln ! ("Debug: manifest_dir = {:?}" , manifest_dir) ; eprintln ! ("Debug: patches_dir = {:?}" , patches_dir) ; if ! patches_dir . exists () { eprintln ! ("Error: No 'patches' directory found at {:?}" , patches_dir) ; return Ok (()) } let config_paths = get_config_paths (& patches_dir) . with_context (| | format ! ("Failed to get config paths from {:?}" , patches_dir)) ? ; if config_paths . is_empty () { eprintln ! ("Error: No edit job files found in {:?}" , patches_dir) ; return Ok (()) } for config_path in config_paths { eprintln ! ("\nDebug: Starting code editing process based on {:?}..." , config_path) ; let config_content = fs :: read_to_string (& config_path) . with_context (| | format ! ("Failed to read {:?}" , config_path)) ? ; let edit_job_config : EditJobConfig = toml :: from_str (& config_content) . with_context (| | format ! ("Failed to parse {:?}" , config_path)) ? ; let mut search_jobs : Vec < & RunSearchDetails > = Vec :: new () ; let mut edits_by_file : HashMap < PathBuf , Vec < & EditJob > > = HashMap :: new () ; for edit in & edit_job_config . edits { match edit { EditJob :: RunSearch (details) => search_jobs . push (details) , _ => { let target_file = match edit { EditJob :: AddUse (details) => & details . target_file , EditJob :: RemoveFunction (details) => & details . target_file , EditJob :: ReplaceExpression (details) => & details . target_file , EditJob :: AddFunction (details) => & details . target_file , EditJob :: AddItem (details) => & details . target_file , EditJob :: ReplaceFileContent (details) => & details . target_file , EditJob :: ReplaceFileContentFromFile (details) => & details . target_file , EditJob :: RemoveCargoDependency (details) => & details . target_file , EditJob :: RemoveUse (details) => & details . target_file , EditJob :: RunSearch (_) => unreachable ! () , } ; eprintln ! ("Debug: Adding edit for target_file: {:?}" , target_file) ; edits_by_file . entry (target_file . clone ()) . or_default () . push (edit) ; } } } for search_job_details in search_jobs { apply_run_search (search_job_details) ? ; } for (file_path , edits) in & mut edits_by_file { eprintln ! ("\nDebug: Processing file: {:?}" , file_path) ; if file_path . file_name () . map_or (false , | name | name == "Cargo.toml") { for edit in edits . drain (..) { if let EditJob :: RemoveCargoDependency (details) = edit { apply_remove_cargo_dependency (details) ? ; } else { eprintln ! ("  Warning: Ignoring non-RemoveCargoDependency edit for Cargo.toml: {:?}" , edit) ; } } let has_rust_edits = edits . iter () . any (| edit | match edit { EditJob :: AddUse (_) | EditJob :: RemoveFunction (_) | EditJob :: ReplaceExpression (_) | EditJob :: AddFunction (_) | EditJob :: AddItem (_) | EditJob :: RemoveUse (_) => true , _ => false , }) ; if ! has_rust_edits { continue ; } } let mut replace_entire_file = false ; let mut new_file_content_from_string : Option < String > = None ; let mut new_file_content_from_file : Option < PathBuf > = None ; for edit in edits . iter () { match edit { EditJob :: ReplaceFileContent (details) => { replace_entire_file = true ; new_file_content_from_string = Some (details . new_content . clone ()) ; break ; } EditJob :: ReplaceFileContentFromFile (details) => { replace_entire_file = true ; new_file_content_from_file = Some (details . source_file . clone ()) ; break ; } _ => { } } } if replace_entire_file { if let Some (content) = new_file_content_from_string { eprintln ! ("Debug: Replacing entire file {:?} with string content." , file_path) ; apply_replace_file_content (& file_path , & content) ? ; eprintln ! ("Successfully replaced content of {:?}" , file_path) ; } else if let Some (source_path) = new_file_content_from_file { eprintln ! ("Debug: Replacing entire file {:?} from source file {:?}." , file_path , source_path) ; apply_replace_file_content_from_file (& file_path , & source_path) ? ; eprintln ! ("Successfully replaced content of {:?} from source file {:?}" , file_path , source_path) ; } } else { let file_content = fs :: read_to_string (& file_path) . with_context (| | format ! ("Failed to read file: {:?}" , file_path)) ? ; eprintln ! ("Debug: Original file content for {:?}:\n{}" , file_path , file_content) ; let mut ast : syn :: File = syn :: parse_file (& file_content) . with_context (| | format ! ("Failed to parse Rust file: {:?}" , file_path)) ? ; for edit in edits . drain (..) { match edit { EditJob :: AddUse (details) => apply_add_use (& mut ast , details) ? , EditJob :: RemoveFunction (details) => apply_remove_function (& mut ast , details) ? , EditJob :: ReplaceExpression (details) => apply_replace_expression (& mut ast , details) ? , EditJob :: AddFunction (details) => apply_add_function (& mut ast , details) ? , EditJob :: AddItem (details) => apply_add_item (& mut ast , details) ? , EditJob :: RemoveUse (details) => apply_remove_use (& mut ast , details) ? , EditJob :: ReplaceFileContent (_) => { { } } EditJob :: ReplaceFileContentFromFile (_) => { { } } EditJob :: RunSearch (_) => unreachable ! () , EditJob :: RemoveCargoDependency (_) => unreachable ! () , } } let formatted_code = prettyplease :: unparse (& ast) ; eprintln ! ("Debug: Formatted code after AST modification for {:?}:\n{}" , file_path , formatted_code) ; fs :: write (& file_path , & formatted_code) . with_context (| | format ! ("Failed to write modified file: {:?}" , file_path)) ? ; } } } eprintln ! ("\nAll specified edits applied successfully!") ; Ok (()) }